package core

import "testing"

func TestSignKeyShare(t *testing.T) {
	ctx := t.Context()
	var req = SignKeyShareRequest{
		Message: "test",
		Signer:  "",
		Commitments: []string{
			"070f0dde390c99f6a10100033cafa331650014b12c5170b0c10af0b674fe3ea286d97c4d45393e834dfa798f037f5e04b3088ad8e0650f7fdedff8592566413ffe10c5ce12c11f40faba8d2c92",
			"07950d277a971e8d9402000256006bd701c26a662f005e5e312f337abd512eeb568dd8a915dce9937fdbc88802f765b9eb4551c65374863ecc59b5210ff17da7e5915367589ec79453a717fe79",
		},
	}

	resp, err := signKeyShare(ctx, req)
	if err != nil {
		t.Error(err)
	}
	t.Log(resp.Signature)
}
